// 提取发布数据
const data = $input.first().json;
const results = data.results || [];

if (results.length === 0) {
  throw new Error('没有已发布的内容需要监测');
}

const items = [];
for (const page of results) {
  const props = page.properties;
  const publishUrl = props['发布链接']?.url || '';

  // 只监测有效链接
  if (publishUrl && !publishUrl.includes('placeholder')) {
    items.push({
      json: {
        publishPageId: page.id,
        publishId: props['发布ID']?.rich_text?.[0]?.text?.content || '',
        title: props['标题']?.title?.[0]?.text?.content || '无标题',
        platform: props['平台']?.select?.name || '',
        publishUrl: publishUrl,
        platformContentId: props['平台内容ID']?.rich_text?.[0]?.text?.content || '',
        publishTime: props['发布时间']?.date?.start || '',
        timestamp: new Date().toISOString()
      }
    });
  }
}

if (items.length === 0) {
  throw new Error('没有有效的发布链接需要监测');
}

return items;

// 根据平台选择抓取策略
const d = $json;

// 注意：各平台数据抓取需要对应的API或爬虫
// 这里提供模拟数据和实现思路

let fetchMethod = '';
let apiEndpoint = '';

switch (d.platform) {
  case '小红书':
    fetchMethod = 'xiaohongshu_api';
    apiEndpoint = `https://www.xiaohongshu.com/discovery/item/${d.platformContentId}`;
    break;
  case '微信公众号':
    fetchMethod = 'wechat_api';
    apiEndpoint = d.publishUrl;
    break;
  case '知乎':
    fetchMethod = 'zhihu_api';
    apiEndpoint = d.publishUrl;
    break;
  default:
    fetchMethod = 'manual';
    apiEndpoint = d.publishUrl;
}

return [{
  json: {
    ...d,
    fetchMethod: fetchMethod,
    apiEndpoint: apiEndpoint
  }
}];

// 抓取数据（模拟）
// 实际应该调用对应平台的API或爬虫

const d = $json;

// 模拟数据（实际应该从API获取）
const mockData = {
  views: Math.floor(Math.random() * 10000) + 100,
  likes: Math.floor(Math.random() * 500) + 10,
  comments: Math.floor(Math.random() * 100) + 1,
  shares: Math.floor(Math.random() * 50) + 1,
  collects: Math.floor(Math.random() * 200) + 5,
  clicks: Math.floor(Math.random() * 300) + 10,
  conversions: Math.floor(Math.random() * 10),
  newFollowers: Math.floor(Math.random() * 20)
};

// 计算互动率
const engagementRate = ((mockData.likes + mockData.comments + mockData.shares) / mockData.views * 100).toFixed(2);

// 计算转化率
const conversionRate = mockData.clicks > 0 ? (mockData.conversions / mockData.clicks * 100).toFixed(2) : 0;

return [{
  json: {
    ...d,
    metrics: mockData,
    engagementRate: parseFloat(engagementRate),
    conversionRate: parseFloat(conversionRate),
    fetchTime: new Date().toISOString(),
    // 实际实现示例：
    // metrics: await fetchPlatformData(d.platform, d.platformContentId)
  }
}];

// 整合监测数据
const d = $json;
const m = d.metrics;

return [{
  json: {
    publishPageId: d.publishPageId,
    publishId: d.publishId,
    title: d.title,
    platform: d.platform,
    collectTime: d.fetchTime,
    views: m.views,
    likes: m.likes,
    comments: m.comments,
    shares: m.shares,
    collects: m.collects,
    clicks: m.clicks,
    conversions: m.conversions,
    newFollowers: m.newFollowers,
    engagementRate: d.engagementRate,
    conversionRate: d.conversionRate,
    dataSnapshot: JSON.stringify(m)
  }
}];

// 构建Notion数据库请求
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_ANALYTICS_DB_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title.substring(0, 100) } }] },
    '平台': { select: { name: d.platform } },
    '采集时间': { date: { start: d.collectTime } },
    '阅读量': { number: d.views },
    '点赞数': { number: d.likes },
    '评论数': { number: d.comments },
    '转发数': { number: d.shares },
    '收藏数': { number: d.collects },
    '互动率': { number: d.engagementRate },
    '点击量': { number: d.clicks },
    '转化数': { number: d.conversions },
    '转化率': { number: d.conversionRate },
    '涨粉数': { number: d.newFollowers },
    '数据快照': { rich_text: [{ text: { content: d.dataSnapshot.substring(0, 2000) } }] }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

