// 生成执行摘要
const items = $input.first().json.data || [];
const successCount = items.filter(item => item.id).length;

// 计算总计数据
let totalViews = 0;
let totalLikes = 0;
let totalComments = 0;
let avgEngagement = 0;

items.forEach(item => {
  const d = item.originalData;
  if (d) {
    totalViews += d.views || 0;
    totalLikes += d.likes || 0;
    totalComments += d.comments || 0;
    avgEngagement += d.engagementRate || 0;
  }
});

if (successCount > 0) {
  avgEngagement = (avgEngagement / successCount).toFixed(2);
}

const summary = `数据监测报告
==================
执行时间: ${new Date().toLocaleString('zh-CN')}

【监测结果】
- 成功: ${successCount}条
- 失败: ${items.length - successCount}条

【数据汇总】
- 总阅读量: ${totalViews.toLocaleString()}
- 总点赞数: ${totalLikes.toLocaleString()}
- 总评论数: ${totalComments.toLocaleString()}
- 平均互动率: ${avgEngagement}%

【TOP内容】
${items.slice(0, 5).map((item, i) => {
  const d = item.originalData;
  return `${i+1}. [${d?.platform}] ${d?.title}\n   阅读:${d?.views} 点赞:${d?.likes} 互动率:${d?.engagementRate}%`;
}).join('\n\n')}

【下一步】
1. 在Notion数据库中查看详细数据
2. 分析高互动内容的特点
3. 优化后续内容策略`;

return [{
  json: {
    report: summary,
    successCount,
    totalCount: items.length,
    totalViews,
    totalLikes,
    totalComments,
    avgEngagement: parseFloat(avgEngagement),
    timestamp: new Date().toISOString()
  }
}];
